 462→/// List all configured workspaces with their live status.
 463→fn cmd_list(backend: &dyn MultiplexerBackend) -> i32 {
 464→    let st = match state::load() {
 465→        Ok(s) => s,
 466→        Err(e) => {
 467→            error!("{e}");
 468→            return 1;
 469→        }
 470→    };
 471→
 472→    let workspaces = st.all_workspaces();
