 622→/// Show workspace URLs.
 623→fn cmd_urls(workspace: Option<String>) -> i32 {
 624→    let st = match state::load() {
 625→        Ok(s) => s,
 626→        Err(e) => {
 627→            error!("{e}");
 628→            return 1;
 629→        }
 630→    };
 631→
 632→    let url_groups = proxy::workspace_urls(&st);
 633→    if url_groups.is_empty() {
 634→        info!("No URLs configured. Add 'ports' to .dual.toml in your repo.");
 635→        return 0;
 636→    }
 637→
 638→    // Filter by workspace if specified
 639→    let filtered: Vec<_> = match &workspace {
 640→        Some(ws) => url_groups.into_iter().filter(|(id, _)| id == ws).collect(),
 641→        None => url_groups,
 642→    };
 643→
 644→    for (workspace_id, urls) in &filtered {
 645→        info!("{workspace_id}");
 646→        for url in urls {
 647→            info!("{url}");
 648→        }
 649→        info!("");
