 660→            error!("{e}");
 661→            return 1;
 662→        }
 663→    };
 664→
 665→    let rt = tokio::runtime::Runtime::new().expect("failed to create tokio runtime");
 666→    match rt.block_on(proxy::start(&st)) {
 667→        Ok(()) => 0,
 668→        Err(e) => {
 669→            error!("proxy failed: {e}");
 670→            1
 671→        }
 672→    }
