 956→/// Derive a short repo name from a directory path.
 957→/// "/Users/jeevan/code/lightfast" → "lightfast"
 958→fn derive_repo_name(path: &std::path::Path) -> String {
 959→    path.file_name()
 960→        .and_then(|n| n.to_str())
 961→        .unwrap_or("repo")
 962→        .to_string()
 963→}
